	addQueryValue(values, "general_tag_id", r.GeneralTagID)
	addOptionalQueryValue(values, "tab", r.Tab)
	addOptionalQueryValue(values, "tag_name", r.TagName)
	addOptionalQueryValue(values, "tag_type", r.TagType)
